    static String readStream(InputStream in,int max)throws IOException{try(InputStream input=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=input.read(b))!=-1){if(out.size()+n>max)throw new IOException("Слишком большой ответ источника");out.write(b,0,n);}return out.toString("UTF-8");}}
    public static String safeUrl(String value){if(value==null||value.trim().isEmpty())return "";value=value.trim().replace(" ","%20").replace("\\/","/").replace("&amp;","&");if(value.startsWith("//"))value="https:"+value;try{Uri u=Uri.parse(value);String h=u.getHost();if(h==null)return "";h=h.toLowerCase(Locale.ROOT);if("http".equals(u.getScheme())&&(h.equals("video.animetop.info")||h.equals("media.animetop.info")||h.equals("static.openni.ru")))u=u.buildUpon().scheme("https").build();String scheme=u.getScheme();if(!("https".equals(scheme)||"http".equals(scheme))||u.getUserInfo()!=null||(!h.contains("."))||h.equals("localhost")||h.endsWith(".local")||h.matches("^(127|10|0|192\\.168|169\\.254)\\..*")||h.matches("^172\\.(1[6-9]|2[0-9]|3[01])\\..*"))return "";return u.toString();}catch(Exception e){return "";}}
    String request(String url,String method,String body,boolean form)throws Exception{return request(url,method,body,form,null);}
    String request(String url,String method,String body,boolean form,Map<String,String> headers)throws Exception{
        String ck=method+" "+url+" "+(body==null?"":body)+" "+(headers==null?"":headers.toString());Cache hit=cache.get(ck);if(hit!=null&&System.currentTimeMillis()-hit.at<45000)return hit.text;
        String current=url;String currentMethod=method,currentBody=body;
        for(int redirect=0;redirect<5;redirect++){
            if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();if(safeUrl(current).isEmpty())throw new IOException("Недопустимый адрес");
            URL target=new URL(current);String host=target.getHost()==null?"":target.getHost().toLowerCase(Locale.ROOT);HttpURLConnection c=(HttpURLConnection)target.openConnection();c.setConnectTimeout(6500);c.setReadTimeout(9500);c.setInstanceFollowRedirects(false);c.setRequestMethod(currentMethod);c.setRequestProperty("Accept","application/json,text/html;q=0.9,*/*;q=0.6");c.setRequestProperty("Accept-Language","ru-RU,ru;q=0.9,en;q=0.5");c.setRequestProperty("User-Agent",CHROME);
            if(headers!=null)for(Map.Entry<String,String> e:headers.entrySet())if(e.getKey()!=null&&e.getValue()!=null)c.setRequestProperty(e.getKey(),e.getValue());
            try{if(currentBody!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type",form?"application/x-www-form-urlencoded; charset=UTF-8":"application/json; charset=UTF-8");try(OutputStream out=c.getOutputStream()){out.write(currentBody.getBytes(StandardCharsets.UTF_8));}}
                int code=c.getResponseCode();if(code>=300&&code<400){String loc=c.getHeaderField("Location");if(loc==null)throw new IOException("Источник не ответил");current=new URL(new URL(current),loc).toString();if(code!=307&&code!=308){currentMethod="GET";currentBody=null;}continue;}
                if(code==429)throw new IOException("Источник временно ограничил частоту запросов. Попробуйте позже.");if(code<200||code>=300)throw new IOException("Источник сейчас недоступен. Попробуйте другой вариант.");String text=readStream(c.getInputStream(),12*1024*1024);if(text.length()<450000)cache.put(ck,new Cache(text));return text;
            }finally{c.disconnect();}
        }
        throw new IOException("Источник не ответил");
    }
    String document(String u)throws Exception{return request(u,"GET",null,false);}
    String formPage(String u,String body)throws Exception{return request(u,"POST",body,true);}
    private JSONObject get(String u)throws Exception{return new JSONObject(request(u,"GET",null,false));}
    private JSONObject postJson(String u,JSONObject j)throws Exception{return new JSONObject(request(u,"POST",j.toString(),false));}
    private JSONObject postForm(String u,String key,String value)throws Exception{return new JSONObject(request(u,"POST",enc(key)+"="+enc(value),true));}
    private static String enc(String s){try{return URLEncoder.encode(s,"UTF-8");}catch(Exception e){return "";}}
    public static String query(String base,Map<String,String> params){StringBuilder s=new StringBuilder(base);for(Map.Entry<String,String> e:params.entrySet()){if(e.getValue()==null||e.getValue().isEmpty())continue;s.append(s.indexOf("?")>=0?'&':'?').append(enc(e.getKey())).append('=').append(enc(e.getValue()));}return s.toString();}
    private static LinkedHashMap<String,String> params(String...kv){LinkedHashMap<String,String> p=new LinkedHashMap<>();for(int i=0;i+1<kv.length;i+=2)p.put(kv[i],kv[i+1]);return p;}
    private JSONObject shiki(String q)throws Exception{JSONObject j=postJson("https://shikimori.io/api/graphql",new JSONObject().put("query",q));if(j.has("errors"))throw new IOException("Источник не ответил на запрос");return j.getJSONObject("data");}
    public Anime.Page catalog(String source,String search,int page,Filter f)throws Exception{
        if(f==null)f=new Filter();if(source==null||source.isEmpty())source="all";if(source.equals("all"))return allCatalog(search,page,f);if(source.equals("animedia"))return new NativeSources(this).catalog(source,search,page);if(source.equals("kodik"))return kodikCatalog(search,page,f);if(source.equals("animelib4k"))return animelib4kCatalog(search,page,f);if(source.equals("animetka"))return animetkaCatalog(search,page,f);if(source.equals("anidub"))return anidubCatalog(search,page);if(source.equals("jutsu"))return jutsuCatalog(search,page);
        Anime.Page out=new Anime.Page();out.page=page;JSONArray rows;String q=search==null?"":search.trim();int limit=24;
        if(source.equals("shikimori")){
            String args="limit:24,page:"+page+",order:"+(f.sort.equals("POPULARITY")?"popularity":"ranked")+",rating:\"!rx\"";
            if(!q.isEmpty())args+=",search:"+JSONObject.quote(q);if(!f.year.isEmpty())args+=",season:"+JSONObject.quote((f.season.isEmpty()?"":f.season+"_")+f.year);if(!f.genre.isEmpty())args+=",genre:"+JSONObject.quote(f.genre);if(!f.type.isEmpty())args+=",kind:"+JSONObject.quote(f.type.toLowerCase(Locale.ROOT));if(!f.status.isEmpty())args+=",status:"+JSONObject.quote(f.status);
            rows=shiki("{animes("+args+"){"+SH_FIELDS+"}}").optJSONArray("animes");for(int i=0;rows!=null&&i<rows.length();i++)out.items.add(remember(shikiAnime(rows.getJSONObject(i))));out.more=rows!=null&&rows.length()==limit;
        }else if(source.equals("animevost")){
            JSONObject data=q.isEmpty()?get("https://api.animevost.org/v1/last?quantity=24&page="+page):postForm("https://api.animevost.org/v1/search","name",q);rows=data.optJSONArray("data");if(rows==null)rows=new JSONArray();if(q.isEmpty()){JSONObject st=data.optJSONObject("state");out.total=st==null?-1:st.optLong("count",-1);for(int i=0;i<rows.length();i++)out.items.add(remember(vostAnime(rows.getJSONObject(i))));out.more=out.total>page*24;}else{out.total=rows.length();for(int i=(page-1)*24;i<Math.min(rows.length(),page*24);i++)out.items.add(remember(vostAnime(rows.getJSONObject(i))));out.more=rows.length()>page*24;}
        }else if(source.equals("yummy")){
            Map<String,String> p=params("limit","24","offset",String.valueOf((page-1)*24),"q",q,"sort",f.sort.equals("YEAR_DESC")?"year":"rating","sort_forward","false","genres",f.genre,"from_year",f.year,"to_year",f.year,"types",f.type.toLowerCase(Locale.ROOT),"status",f.status.equals("anons")?"announcement":f.status);JSONObject data=get(query("https://api.yani.tv/anime",p));if(data.has("error"))throw new IOException("Источник сейчас недоступен");rows=data.optJSONArray("response");for(int i=0;rows!=null&&i<rows.length();i++)out.items.add(remember(yummyAnime(rows.getJSONObject(i))));out.more=rows!=null&&rows.length()==24;
        }else if(source.equals("animelib")){
            Map<String,String> p=params("page",String.valueOf(page),"q",q,"sort_by",f.sort.equals("FRESH_AT_DESC")?"last_episode_at":"rate_avg");String u=query("https://api.cdnlibs.org/api/anime",p)+"&fields%5B%5D=rate&fields%5B%5D=rate_avg&fields%5B%5D=releaseDate";if(!f.status.isEmpty())u+="&status%5B%5D="+(f.status.equals("ongoing")?"1":"2");JSONObject data=get(u);rows=data.optJSONArray("data");for(int i=0;rows!=null&&i<rows.length();i++)out.items.add(remember(amAnime(rows.getJSONObject(i))));JSONObject links=data.optJSONObject("links");out.more=links!=null&&!links.isNull("next")&&!links.optString("next","").isEmpty();
        }else if(source.equals("anilibria")){
            Map<String,String> p=params("limit","24","page",String.valueOf(page),"f[search]",q,"f[sorting]",f.sort.equals("POPULARITY")?"RATING_DESC":f.sort,"f[genres]",f.genre,"f[types]",f.type,"f[years][from_year]",f.year,"f[years][to_year]",f.year,"f[publish_statuses]",f.status.isEmpty()?"":f.status.equals("ongoing")?"IS_ONGOING":"IS_NOT_ONGOING");JSONObject data=get(query("https://anilibria.top/api/v1/anime/catalog/releases",p));rows=data.optJSONArray("data");for(int i=0;rows!=null&&i<rows.length();i++)out.items.add(remember(libriaAnime(rows.getJSONObject(i))));JSONObject meta=data.optJSONObject("meta"),pg=meta==null?null:meta.optJSONObject("pagination");if(pg!=null){out.total=pg.optLong("total",-1);out.more=page<pg.optInt("total_pages");}
        }else throw new IOException("Неизвестный источник");
        if(out.total>=0&&q.isEmpty()&&f.genre.isEmpty()&&f.year.isEmpty()&&f.type.isEmpty()&&f.status.isEmpty())counts.put(source,out.total);return out;
    }
    private Anime.Page allCatalog(String search,int page,Filter f)throws Exception{Anime.Page out=new Anime.Page();out.page=page;LinkedHashMap<String,Anime> items=new LinkedHashMap<>();boolean more=false;int ok=0;ExecutorService pool=Executors.newFixedThreadPool(REAL_SOURCES.length);CompletionService<Anime.Page> done=new ExecutorCompletionService<>(pool);for(String source:REAL_SOURCES){final String src=source;done.submit(()->catalog(src,search,page,f));}long deadline=System.currentTimeMillis()+((search==null||search.trim().isEmpty())?5200:6500);try{for(int i=0;i<REAL_SOURCES.length;i++){long left=deadline-System.currentTimeMillis();if(left<=0)break;Future<Anime.Page> future=done.poll(left,TimeUnit.MILLISECONDS);if(future==null)break;try{Anime.Page p=future.get();ok++;more|=p.more;for(Anime a:p.items)items.put(a.key(),a);if(items.size()>=24&&ok>=2)break;}catch(Exception ignored){}}}finally{pool.shutdownNow();}out.items.addAll(items.values());out.more=more;if((search==null||search.trim().isEmpty())&&countOf("all")>0)out.total=countOf("all");if(out.items.isEmpty()&&ok==0)throw new IOException("Источники сейчас недоступны");return out;}
    public Anime details(Anime base,boolean episodes)throws Exception{
        if(base.source.equals("animedia"))return new NativeSources(this).details(base,episodes);
        Anime a;String id=base.id;
        switch(base.source){
            case "shikimori":{JSONArray rows=shiki("{animes(ids:"+JSONObject.quote(id)+",limit:1){"+SH_FIELDS+" descriptionHtml related{relationKind anime{"+SH_FIELDS+"}}}}").optJSONArray("animes");if(rows==null||rows.length()==0)throw new IOException("Аниме не найдено");JSONObject j=rows.getJSONObject(0);a=shikiAnime(j);a.description=plain(j.optString("descriptionHtml"));JSONArray rel=j.optJSONArray("related");for(int i=0;rel!=null&&i<rel.length();i++){JSONObject r=rel.getJSONObject(i).optJSONObject("anime");if(r!=null)a.related.add(remember(shikiAnime(r)));}break;}
            case "animevost":{JSONArray rows=postForm("https://api.animevost.org/v1/info","id",id).optJSONArray("data");if(rows==null||rows.length()==0)throw new IOException("Аниме не найдено");a=vostAnime(rows.getJSONObject(0));if(episodes){JSONArray list=new JSONArray(request("https://api.animevost.org/v1/playlist","POST","id="+enc(id),true));for(int i=0;i<list.length();i++){JSONObject e=list.getJSONObject(i);Anime.Episode ep=new Anime.Episode();ep.id=id+"-"+i;ep.name=e.optString("name","");ep.number=numberIn(ep.name,i+1);putStream(ep,480,e.optString("std"));putStream(ep,720,e.optString("hd"));a.episodeList.add(ep);}a.episodes=Math.max(a.episodes,a.episodeList.size());}break;}
            case "yummy":{JSONObject d=get("https://api.yani.tv/anime/"+enc(id)).optJSONObject("response");if(d==null)throw new IOException("YummyAnime не вернул карточку");a=yummyAnime(d);if(episodes){a.episodeList.addAll(YummyParser.episodes(id));a.episodes=Math.max(a.episodes,a.episodeList.size());}break;}
            case "anidub":{a=anidubDetails(base,episodes);break;}
            case "jutsu":{a=jutsuDetails(base,episodes);break;}
            case "animelib":{String slug=base.alias.isEmpty()?id:base.alias;JSONObject d=animelibDetail(slug,base).getJSONObject("data");a=amAnime(d);if(episodes){JSONArray rows=get("https://api.cdnlibs.org/api/episodes?anime_id="+enc(a.alias)).optJSONArray("data");for(int i=0;rows!=null&&i<rows.length();i++){JSONObject e=rows.getJSONObject(i);double n=e.optDouble("number",-1);if(n<0||!Double.isFinite(n))continue;Anime.Episode ep=new Anime.Episode();ep.id=e.optString("id");ep.number=n;ep.name=e.optString("name","");ep.lazy="animelib";a.episodeList.add(ep);}a.episodeList.sort(Comparator.comparingDouble(e->e.number));a.episodes=a.episodeList.size();}break;}
            case "animelib4k":{Anime copy=Anime.from(base.json());copy.source="animelib";a=details(copy,episodes);a.source="animelib4k";break;}
            case "anilibria":{a=libriaAnime(get("https://anilibria.top/api/v1/anime/releases/"+enc(id)));break;}
            case "animetka":{a=animetkaDetails(base,episodes);break;}
            case "kodik":{a=kodikDetails(base,episodes);break;}
            default:throw new IOException("Неизвестный источник");
        }
        if(a.year==0)a.year=base.year;if(a.malId==0)a.malId=base.malId;if(a.kpId==0)a.kpId=base.kpId;if(a.description.isEmpty())a.description=base.description;if(a.poster.isEmpty())a.poster=base.poster;return remember(a);
    }
    public Anime.Playback playback(Anime input,String selectedMode)throws Exception{
        normalizeIds(input);
        String selected=selectedMode==null||selectedMode.trim().isEmpty()?"auto":selectedMode.trim();
        if(selected.equals("all"))selected="auto";
        if(!selected.equals("auto")){
            Anime video=findPlayableSource(input,selected);
            if(video==null)throw new IOException("Источник сейчас не вернул серии");
            return playbackResult(input,video,selected);
        }
        ArrayList<String> order=new ArrayList<>();
        if(Arrays.asList("animevost","anilibria","animedia","animelib","animelib4k","yummy","animetka","anidub","jutsu","kodik").contains(input.source))order.add(input.source);
        for(String source:new String[]{"yummy","anilibria","animevost","animelib","animedia"})if(!order.contains(source))order.add(source);
        ExecutorService pool=Executors.newFixedThreadPool(Math.max(1,Math.min(4,order.size())));
        CompletionService<Anime.Playback> done=new ExecutorCompletionService<>(pool);
        for(String source:order){final String src=source;done.submit(()->{Anime video=findPlayableSource(input,src);return video==null?null:playbackResult(input,video,src);});}
        long deadline=System.currentTimeMillis()+9500;
        try{for(int i=0;i<order.size();i++){long left=deadline-System.currentTimeMillis();if(left<=0)break;Future<Anime.Playback> f=done.poll(left,TimeUnit.MILLISECONDS);if(f==null)break;try{Anime.Playback r=f.get();if(r!=null)return r;}catch(Exception ignored){}}}finally{pool.shutdownNow();}
        throw new IOException("Источники сейчас не вернули серии");
    }
    private Anime.Playback playbackResult(Anime catalog,Anime video,String provider){Anime.Playback r=new Anime.Playback();r.catalog=catalog;r.video=video;r.provider=provider==null||provider.isEmpty()?video.source:provider;return r;}
    private Anime findPlayableSource(Anime input,String source){try{Anime candidate=findSourceCandidate(input,source);if(candidate==null)return null;Anime full=candidate.episodeList.isEmpty()?details(candidate,true):candidate;if(!full.blocked&&!full.episodeList.isEmpty())return full;}catch(Exception ignored){}return null;}
    private Anime findSourceCandidate(Anime input,String source)throws Exception{
        if(source.equals(input.source)&&Arrays.asList("animevost","anilibria","animedia","animelib","animelib4k","yummy","animetka","anidub","jutsu","kodik").contains(source))return input;
        if(source.equals("yummy"))return findYummy(input);
        if(source.equals("anilibria")){Anime v=findAniLiberty(input);if(v!=null)return v;}
        if(source.equals("animelib")){Anime v=findAniLib(input);if(v!=null)return v;}
        if(source.equals("kodik"))return kodikShell(input);
        if(source.equals("animetka")||source.equals("anidub")||source.equals("jutsu"))return searchSource(input,source);
        if(source.equals("animelib4k")){Anime v=findAniLib(input);if(v!=null){v.source="animelib4k";return v;}}
        if(Arrays.asList("animevost","animedia").contains(source))return searchSource(input,source);
        return null;
    }
    public synchronized void loadEpisode(Anime.Episode ep)throws Exception{if(ep.lazy.equals("animedia")){new NativeSources(this).loadEpisode(ep);return;}if(ep.lazy.equals("jutsu")){loadJutsuEpisode(ep);return;}if(ep.lazy.equals("anidub")){if(ep.variants.isEmpty()&&!ep.resolverUrl.isEmpty())ep.variants.add(new Anime.Variant("AniDub",hostName(ep.resolverUrl),ep.resolverUrl));return;}if(ep.lazy.equals("kodik")){if(ep.variants.isEmpty())ep.variants.add(new Anime.Variant("Kodik 2026","Kodik",ep.resolverUrl));return;}if(!"animelib".equals(ep.lazy)||!ep.variants.isEmpty())return;JSONObject d=get("https://api.cdnlibs.org/api/episodes/"+enc(ep.id)).getJSONObject("data");JSONArray rows=d.optJSONArray("players");for(int i=0;rows!=null&&i<rows.length();i++){JSONObject v=rows.getJSONObject(i);if(!v.optString("player").equalsIgnoreCase("kodik"))continue;String u=embed(v.optString("src"));if(u.isEmpty())continue;JSONObject team=v.optJSONObject("team"),t=v.optJSONObject("translation_type");String name=(t==null?"Озвучка":t.optString("label","Озвучка"))+" "+(team==null?"":team.optString("name",""));ep.variants.add(new Anime.Variant(name.trim(),"Kodik",u));}if(ep.variants.isEmpty())throw new IOException("У серии нет доступного плеера");}
    public static final class DownloadOption {public Anime source;public Anime.Episode episode;public int quality;public String voice="",player="";public DownloadOption(Anime a,Anime.Episode e,int q){source=a;episode=e;quality=q;}public DownloadOption(Anime a,Anime.Episode e,int q,String v,String p){source=a;episode=e;quality=q;voice=v==null?"":v;player=p==null?"":p;}public String label(){String sourceName=downloadSourceName(source.source);String extra=voice.isEmpty()?"":voice;String p=player.isEmpty()?"":" · "+player;return (quality>0?quality+"p":"Оригинал")+" · "+sourceName+(extra.isEmpty()?"":" · "+extra)+p;}}
    private List<DownloadOption> options(Anime source,double number)throws Exception{ArrayList<DownloadOption> out=new ArrayList<>();if(source==null||source.blocked)return out;for(Anime.Episode e:source.episodeList)if(sameEpisode(e.number,number)){try{loadEpisode(e);}catch(Exception ignored){}for(int q:e.streams.keySet())out.add(new DownloadOption(source,e,q));if(!e.variants.isEmpty())out.addAll(variantOptions(source,e));break;}return uniqueOptions(out);}
    private List<DownloadOption> variantOptions(Anime source,Anime.Episode episode){ArrayList<DownloadOption> out=new ArrayList<>();if(episode.variants.isEmpty())return out;ExecutorService pool=Executors.newFixedThreadPool(Math.max(1,Math.min(6,episode.variants.size())));ArrayList<Future<List<DownloadOption>>> jobs=new ArrayList<>();for(Anime.Variant v:episode.variants)jobs.add(pool.submit(()->{ArrayList<DownloadOption> rows=new ArrayList<>();try{TreeMap<Integer,String> streams=VideoResolver.resolve(this,v.url);if(streams.isEmpty())return rows;Anime.Episode copy=new Anime.Episode();copy.id=episode.id+"-"+Integer.toHexString((v.name+"|"+v.player+"|"+v.url).hashCode());copy.number=episode.number;copy.name=v.label();copy.duration=v.duration;copy.openingStart=v.openingStart;copy.openingEnd=v.openingEnd;copy.streams.putAll(streams);for(int q:copy.streams.keySet())rows.add(new DownloadOption(source,copy,q,v.label(),v.player));}catch(Exception ignored){}return rows;}));long deadline=System.currentTimeMillis()+65000;for(Future<List<DownloadOption>> job:jobs){long left=deadline-System.currentTimeMillis();if(left<=0){job.cancel(true);continue;}try{out.addAll(job.get(left,TimeUnit.MILLISECONDS));}catch(Exception ignored){job.cancel(true);}}pool.shutdownNow();return out;}
    private void collectOptions(ArrayList<DownloadOption> out,LinkedHashSet<String> tried,Anime source,double number){if(source==null)return;String key="options|"+source.key()+"|"+number;if(!tried.add(key))return;try{out.addAll(options(source,number));}catch(Exception ignored){}}
    private void collectDetailsOptions(ArrayList<DownloadOption> out,LinkedHashSet<String> tried,Anime source,double number){if(source==null)return;String key="details|"+source.key()+"|"+number;if(!tried.add(key))return;try{collectOptions(out,tried,details(source,true),number);}catch(Exception ignored){}}
    private void collectCatalogMatches(ArrayList<DownloadOption> out,LinkedHashSet<String> tried,Anime base,String source,double number){int found=0;for(String term:searchTerms(base)){try{Anime.Page page=catalog(source,term,1,new Filter());for(Anime item:page.items){if(!matchesAnime(item,base))continue;collectDetailsOptions(out,tried,item,number);found++;if(found>=3)return;}}catch(Exception ignored){}}}
    private void collectDirectKodik(ArrayList<DownloadOption> out,LinkedHashSet<String> tried,Anime base,double number){try{int mal=base.malId>0?base.malId:resolveMal(base);String url=directKodik(mal);if(url.isEmpty())return;Uri u=Uri.parse(url);String path=u.getPath();if(path==null||!path.startsWith("/video/"))url=u.buildUpon().appendQueryParameter("episode",episodeParam(number)).build().toString();collectIframeOptions(out,tried,base,"kodik","Kodik","Kodik",url,number);}catch(Exception ignored){}}
    private void collectIframeOptions(ArrayList<DownloadOption> out,LinkedHashSet<String> tried,Anime base,String sourceId,String sourceTitle,String player,String iframe,double number){String url=embed(iframe);if(url.isEmpty())return;String key="iframe|"+sourceId+"|"+number+"|"+url;if(!tried.add(key))return;try{TreeMap<Integer,String> streams=VideoResolver.resolve(this,url);if(streams.isEmpty())return;Anime source=new Anime();source.source=sourceId;source.id=(base.key()+"|"+sourceId+"|"+Integer.toHexString(url.hashCode())).replace(':','_');source.title=sourceTitle;source.original=base.original;source.poster=base.poster;source.description=base.description;source.year=base.year;source.type=base.type;source.status=base.status;source.episodes=base.episodes;source.malId=base.malId;source.anilistId=base.anilistId;source.kpId=base.kpId;Anime.Episode ep=new Anime.Episode();ep.id=source.id+"-"+episodeParam(number);ep.number=number;ep.name=sourceTitle;ep.streams.putAll(streams);for(int q:streams.keySet())out.add(new DownloadOption(source,ep,q,sourceTitle,player));}catch(Exception ignored){}}
    private static ArrayList<DownloadOption> uniqueOptions(List<DownloadOption> options){LinkedHashMap<String,DownloadOption> unique=new LinkedHashMap<>();for(DownloadOption d:options){if(d==null||d.episode==null)continue;String url=d.episode.streams.get(d.quality);String safe=safeUrl(url);if(safe.isEmpty())continue;unique.put((d.source==null?"":d.source.source)+"|"+d.quality+"|"+d.voice+"|"+d.player+"|"+safe,d);}ArrayList<DownloadOption> list=new ArrayList<>(unique.values());list.sort((a,b)->{int s=downloadSourceRank(a.source.source)-downloadSourceRank(b.source.source);if(s!=0)return s;int q=Integer.compare(b.quality,a.quality);if(q!=0)return q;return a.label().compareToIgnoreCase(b.label());});return list;}
    public List<DownloadOption> downloadOptions(Anime a,Anime.Playback current,double number)throws Exception{
        ArrayList<DownloadOption> out=new ArrayList<>();if(a==null||a.blocked)return out;normalizeIds(a);LinkedHashSet<String> tried=new LinkedHashSet<>();
        if(current!=null){collectOptions(out,tried,current.video,number);if(!current.directUrl.isEmpty())collectIframeOptions(out,tried,a,current.provider.isEmpty()?"player":current.provider,current.provider.isEmpty()?"Плеер":current.provider,current.directKodik?"Kodik":"Iframe",current.directUrl,number);}
        if(Arrays.asList("animevost","anilibria","animedia","animelib","animelib4k","yummy","animetka","anidub","jutsu","kodik").contains(a.source))collectDetailsOptions(out,tried,a,number);
        Anime y=null;try{y=findYummy(a);if(y!=null)collectDetailsOptions(out,tried,y,number);}catch(Exception ignored){}
        collectDirectKodik(out,tried,a,number);
        try{String alias=a.libriaAlias.isEmpty()?(y==null?"":y.libriaAlias):a.libriaAlias;if(!alias.isEmpty())collectOptions(out,tried,libriaAnime(get("https://anilibria.top/api/v1/anime/releases/"+enc(alias))),number);}catch(Exception ignored){}
        for(String source:new String[]{"anilibria","animevost","animelib","animedia","animetka","anidub"})collectCatalogMatches(out,tried,a,source,number);
        return uniqueOptions(out);
    }

    private Anime.Page animetkaCatalog(String search,int page,Filter f)throws Exception{Anime.Page out=new Anime.Page();out.page=page;String q=search==null?"":search.trim();int limit=24,offset=Math.max(0,(page-1)*limit);String url=q.isEmpty()?query("https://animetka.com/api/anime/top",params("limit",String.valueOf(limit),"offset",String.valueOf(offset))):query("https://animetka.com/api/anime/search",params("name",q,"limit",String.valueOf(limit),"offset",String.valueOf(offset)));JSONArray rows=new JSONArray(request(url,"GET",null,false,animetkaHeaders()));if(rows.length()==0&&!q.isEmpty())rows=new JSONArray(request(query("https://animetka.com/api/anime/search",params("q",q,"limit",String.valueOf(limit),"offset",String.valueOf(offset))),"GET",null,false,animetkaHeaders()));int end=Math.min(rows.length(),limit);for(int i=0;i<end;i++){Anime a=animetkaAnime(rows.getJSONObject(i));if(Anime.valid(a))out.items.add(remember(a));}out.more=!q.isEmpty()&&rows.length()==limit;return out;}
    private Anime animetkaDetails(Anime base,boolean episodes)throws Exception{JSONObject d=new JSONObject(request("https://animetka.com/api/anime/"+enc(base.id),"GET",null,false,animetkaHeaders()));Anime a=animetkaAnime(d);if(!Anime.valid(a)){a=Anime.from(base.json());a.source="animetka";}JSONArray rel=d.optJSONArray("franchise");for(int i=0;rel!=null&&i<rel.length();i++){JSONObject r=rel.optJSONObject(i);if(r!=null){Anime item=animetkaAnime(r);if(Anime.valid(item)&&!item.id.equals(a.id))a.related.add(remember(item));}}if(episodes){LinkedHashMap<String,Anime.Episode> map=new LinkedHashMap<>();JSONObject lm=d.optJSONObject("AnilibriaMapping");JSONArray le=lm==null?null:lm.optJSONArray("episodes");for(int i=0;le!=null&&i<le.length();i++){JSONObject e=le.optJSONObject(i);if(e==null)continue;double n=e.optDouble("ordinal",i+1);String key=episodeParam(n);Anime.Episode ep=map.get(key);if(ep==null){ep=new Anime.Episode();ep.id=a.id+"-"+key;ep.number=n;ep.name=e.optString("name","");map.put(key,ep);}if(ep.name.isEmpty())ep.name="AniLibria";ep.duration=e.optInt("duration",ep.duration);putStream(ep,480,e.optString("hls_480"));putStream(ep,720,e.optString("hls_720"));putStream(ep,1080,e.optString("hls_1080"));JSONObject op=e.optJSONObject("opening");if(op!=null){ep.openingStart=op.optInt("start",ep.openingStart);ep.openingEnd=op.optInt("stop",ep.openingEnd);}}JSONArray rows=d.optJSONArray("Animes");HashMap<Integer,String> names=animetkaTranslationNames(d,rows);for(int i=0;rows!=null&&i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row==null)continue;String link=embed(row.optString("link"));if(link.isEmpty())continue;int tid=row.optInt("translation",0),count=Math.max(row.optInt("episodes_total",0),row.optInt("episodes_aired",0));if(count<=0)count=a.episodes>0?a.episodes:1;if(row.optString("kodik_id").startsWith("movie-")||Uri.parse(link).getPath()!=null&&Uri.parse(link).getPath().startsWith("/video/"))count=1;count=Math.max(1,Math.min(250,count));String voice=names.get(tid);if(voice==null||voice.isEmpty())voice=tid>0?"Перевод "+tid:"Kodik";String q=row.optString("quality","").replace("WEB-DLRip ","").trim();for(int n=1;n<=count;n++){String key=episodeParam(n);Anime.Episode ep=map.get(key);if(ep==null){ep=new Anime.Episode();ep.id=a.id+"-"+key;ep.number=n;map.put(key,ep);}String url=animetkaEpisodeUrl(link,n);Anime.Variant v=new Anime.Variant(voice,"Kodik",url);v.displayName=voice+(q.isEmpty()?"":" · "+q);addVariant(ep,v);}}a.episodeList.clear();a.episodeList.addAll(map.values());a.episodeList.sort(Comparator.comparingDouble(e->e.number));a.episodes=Math.max(a.episodes,a.episodeList.size());}return remember(a);}
    private HashMap<Integer,String> animetkaTranslationNames(JSONObject detail,JSONArray rows){HashMap<Integer,String> out=new HashMap<>();int material=detail.optInt("id",detail.optInt("animetka_id",0)),tid=0;for(int i=0;rows!=null&&i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row!=null&&row.optInt("translation",0)>0){tid=row.optInt("translation");break;}}if(material<=0||tid<=0)return out;try{JSONObject p=new JSONObject(request(query("https://animetka.com/api/anime/playlist",params("material",String.valueOf(material),"tid",String.valueOf(tid))),"GET",null,false,animetkaHeaders()));JSONArray list=p.optJSONArray("translations");for(int i=0;list!=null&&i<list.length();i++){JSONObject t=list.optJSONObject(i);if(t!=null)out.put(t.optInt("value",t.optInt("id",0)),t.optString("name",t.optString("title","")));}}catch(Exception ignored){}return out;}
    private static String animetkaEpisodeUrl(String link,int episode){try{Uri u=Uri.parse(link);String path=u.getPath();if(path!=null&&path.startsWith("/video/"))return link;return u.buildUpon().appendQueryParameter("episode",String.valueOf(episode)).build().toString();}catch(Exception e){return link;}}
    private static void addVariant(Anime.Episode ep,Anime.Variant v){for(Anime.Variant old:ep.variants)if(old.url.equals(v.url)&&old.name.equals(v.name)&&old.player.equals(v.player))return;ep.variants.add(v);}
    private static HashMap<String,String> animetkaHeaders(){HashMap<String,String> h=new HashMap<>();h.put("Accept","application/json,text/plain,*/*");h.put("Accept-Language","ru-RU,ru;q=0.9,en;q=0.5");h.put("Origin","https://animetka.com");h.put("Referer","https://animetka.com/");h.put("User-Agent","Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/149.0.0.0 Mobile Safari/537.36");return h;}


    private Anime.Page anidubCatalog(String search,int page)throws Exception{Anime.Page out=new Anime.Page();out.page=page;String q=search==null?"":search.trim();String url=q.isEmpty()?(page<=1?"https://online.anidub.com/":"https://online.anidub.com/page/"+page+"/"):query("https://online.anidub.com/index.php",params("do","search","subaction","search","story",q));Document doc=Jsoup.parse(document(url),url);LinkedHashMap<String,Anime> map=new LinkedHashMap<>();for(Element a:doc.select("a[href]")){String href=absolute(url,a.attr("href"));if(href.isEmpty()||href.contains("/user/")||href.contains("/anidub_news/")||!Pattern.compile("/(\\d+)-[^/]+\\.html(?:$|[?#])").matcher(href).find())continue;Element scope=cardScope(a);String title=anchorTitle(a);if(title.isEmpty()||title.length()<2||title.matches("[+\\-]?[0-9.]+"))continue;Anime item=anidubShell(href,title,posterFrom(url,scope),scope==null?title:scope.text());if(q.isEmpty()||matchesQuery(item,q))putBetter(map,item);if(map.size()>=24)break;}out.items.addAll(map.values());out.more=q.isEmpty()&&out.items.size()>=18;return out;}
    private Anime anidubDetails(Anime base,boolean episodes)throws Exception{String url=sourceUrl(base);String html=document(url);Document doc=Jsoup.parse(html,url);Anime a=anidubShell(url,heading(doc,base.title),posterFrom(url,doc),doc.text());String desc=descriptionFrom(doc);if(!desc.isEmpty())a.description=desc;for(Element g:doc.select("a[href*=/xfsearch/genre/],a[href*=/genre/]") ){String t=cleanText(g.text());if(!t.isEmpty()&&!a.genres.contains(t))a.genres.add(t);}if(episodes){LinkedHashMap<String,Anime.Episode> map=new LinkedHashMap<>();anidubOptions(doc,html,url,"sel","Sibnet",map,a.id);anidubOptions(doc,html,url,"sel2","AniDub",map,a.id);anidubOptions(doc,html,url,"sel3","Stormo",map,a.id);if(map.isEmpty())anidubDirectFallback(a,html,url);else{a.episodeList.clear();a.episodeList.addAll(map.values());a.episodeList.sort(Comparator.comparingDouble(e->e.number));a.episodes=Math.max(a.episodes,a.episodeList.size());}}return remember(a);}
    private void anidubOptions(Document doc,String html,String page,String id,String player,LinkedHashMap<String,Anime.Episode> map,String baseId){for(Element o:doc.select("#"+id+" option"))anidubOption(page,player,o.attr("value"),o.text(),map,baseId);Matcher box=Pattern.compile("<select[^>]+id=[\\\"']"+Pattern.quote(id)+"[\\\"'][^>]*>(.*?)</select>",Pattern.CASE_INSENSITIVE|Pattern.DOTALL).matcher(html);while(box.find()){Matcher m=Pattern.compile("<option[^>]+value=[\\\"']([^\\\"']+)[\\\"'][^>]*>(.*?)</option>",Pattern.CASE_INSENSITIVE|Pattern.DOTALL).matcher(box.group(1));while(m.find())anidubOption(page,player,unescape(m.group(1)),plain(m.group(2)),map,baseId);}}
    private void anidubOption(String page,String suggested,String value,String label,LinkedHashMap<String,Anime.Episode> map,String baseId){String v=unescape(value);if(v.isEmpty())return;int cut=v.lastIndexOf('|');String raw=cut>0?v.substring(0,cut):v,num=cut>0?v.substring(cut+1):label;String provider=absolute(page,raw);if(provider.isEmpty())return;double n=numberIn(num+" "+label,map.size()+1);if(n<=0||!Double.isFinite(n))n=map.size()+1;String key=episodeParam(n);Anime.Episode ep=map.get(key);if(ep==null){ep=new Anime.Episode();ep.id=baseId+"-"+key;ep.number=n;ep.name="AniDub";ep.lazy="anidub";map.put(key,ep);}String h=hostName(provider).toLowerCase(Locale.ROOT),p=suggested;if(h.contains("sibnet"))p="Sibnet";else if(h.contains("stormo"))p="Stormo";else if(h.contains("ladony")||provider.contains("vid.php"))p="AniDub HLS";Anime.Variant variant=new Anime.Variant("AniDub",p,provider);variant.displayName="AniDub · "+p;addVariant(ep,variant);}
    private void anidubDirectFallback(Anime a,String html,String page){Matcher m=Pattern.compile("https?:\\\\?/\\\\?/[^\\\"'<>\\s]+?(?:\\.m3u8|\\.mp4)[^\\\"'<>\\s]*",Pattern.CASE_INSENSITIVE).matcher(html);Anime.Episode ep=null;while(m.find()){String safe=safeUrl(m.group().replace("\\/","/"));if(safe.isEmpty())continue;if(ep==null){ep=new Anime.Episode();ep.id=a.id+"-1";ep.number=1;ep.name="AniDub";a.episodeList.add(ep);}putStream(ep,VideoResolver.qualityOf(safe),safe);}if(ep!=null){a.episodes=Math.max(a.episodes,1);return;}Matcher iframe=Pattern.compile("<(?:iframe|embed)[^>]+src=[\\\"']([^\\\"']+)[\\\"']",Pattern.CASE_INSENSITIVE).matcher(html);while(iframe.find()){String u=embed(absolute(page,iframe.group(1)));if(u.isEmpty())continue;if(ep==null){ep=new Anime.Episode();ep.id=a.id+"-1";ep.number=1;ep.name="AniDub";ep.lazy="anidub";a.episodeList.add(ep);}Anime.Variant v=new Anime.Variant("AniDub",hostName(u),u);v.displayName="AniDub · "+hostName(u);addVariant(ep,v);}if(ep!=null)a.episodes=Math.max(a.episodes,1);}
    private Anime.Page jutsuCatalog(String search,int page)throws Exception{Anime.Page out=new Anime.Page();out.page=page;String q=search==null?"":search.trim();LinkedHashMap<String,Anime> map=new LinkedHashMap<>();ArrayList<String> urls=new ArrayList<>();if(q.isEmpty())urls.add(page<=1?"https://jut.su/anime/":"https://jut.su/anime/page-"+page+"/");else{urls.add("https://jut.su/anime/");urls.add("https://jut.su/anime/page-2/");urls.add("https://jut.su/anime/ongoing/");urls.add("https://jut.su/anime/order-by-name/");}for(String url:urls){try{Document doc=Jsoup.parse(document(url),url);for(Element a:doc.select("a[href]")){String href=absolute(url,a.attr("href"));if(!jutsuTitleUrl(href))continue;Anime item=jutsuShell(href,anchorTitle(a),posterFrom(url,cardScope(a)),cardScope(a)==null?a.text():cardScope(a).text());if(item.title.length()<2)continue;if(q.isEmpty()||matchesQuery(item,q))putBetter(map,item);if(map.size()>=24)break;}}catch(Exception ignored){}if(map.size()>=24)break;}if(map.isEmpty()&&!q.isEmpty()){String slug=latinSlug(q);if(!slug.isEmpty())try{String url="https://jut.su/"+slug+"/";Anime seed=jutsuShell(url,q,"",q);Anime item=jutsuDetails(seed,false);if(matchesQuery(item,q))putBetter(map,item);}catch(Exception ignored){}}out.items.addAll(map.values());out.more=q.isEmpty()&&out.items.size()>=18;return out;}
    private Anime jutsuDetails(Anime base,boolean episodes)throws Exception{String url=sourceUrl(base);String html=document(url);Document doc=Jsoup.parse(html,url);Anime a=jutsuShell(url,heading(doc,base.title),posterFrom(url,doc),doc.text());String original=findText(html,"Оригинальное название:\\s*</?[^>]*>\\s*([^<\\n]+)");if(!original.isEmpty())a.original=cleanText(original);String desc=descriptionFrom(doc);if(!desc.isEmpty())a.description=desc;for(Element g:doc.select("a[href*=/anime/]") ){String href=g.attr("href"),t=cleanText(g.text());if(t.isEmpty()||href.matches(".*/anime/(?:page|order|ongoing|before2000|20[0-9]{2}|[0-9-]+)/?.*"))continue;if(!a.genres.contains(t))a.genres.add(t);}if(episodes){LinkedHashSet<String> seen=new LinkedHashSet<>();int seq=1;for(Element link:doc.select("a[href*=episode-][href$=.html],a.video[href]")){String href=absolute(url,link.attr("href"));if(href.isEmpty()||!href.contains("episode-")||!seen.add(href))continue;Anime.Episode ep=new Anime.Episode();ep.id=a.id+"-"+seq;ep.number=seq;ep.name=episodeTitle(link.text(),seq);ep.lazy="jutsu";ep.resolverUrl=href;a.episodeList.add(ep);seq++;}for(Element link:doc.select("a[href*=film][href]")){String href=absolute(url,link.attr("href"));if(href.isEmpty()||!jutsuTitleUrl(href)||!seen.add(href))continue;Anime.Episode ep=new Anime.Episode();ep.id=a.id+"-"+seq;ep.number=seq;ep.name=episodeTitle(link.text(),seq);ep.lazy="jutsu";ep.resolverUrl=href;a.episodeList.add(ep);seq++;}a.episodes=Math.max(a.episodes,a.episodeList.size());}return remember(a);}
    private void loadJutsuEpisode(Anime.Episode ep)throws Exception{if(!ep.streams.isEmpty())return;String url=safeUrl(ep.resolverUrl);if(url.isEmpty())throw new IOException("Серия недоступна");String html=document(url);Document doc=Jsoup.parse(html,url);for(Element s:doc.select("video#my-player source[src],video source[src],source[src]")){String src=absolute(url,s.attr("src"));if(src.isEmpty())continue;int q=parseInt(first(first(s.attr("res"),s.attr("label")),first(s.attr("data-res"),s.attr("data-quality"))));if(q<=0)q=VideoResolver.qualityOf(src);putStream(ep,q,src);}if(ep.streams.isEmpty()){Matcher m=Pattern.compile("https?:\\\\?/\\\\?/[^\\\"'<>\\s]+?(?:\\.m3u8|\\.mp4)[^\\\"'<>\\s]*",Pattern.CASE_INSENSITIVE).matcher(html);while(m.find()){String safe=safeUrl(m.group().replace("\\/","/"));if(safe.isEmpty())continue;TreeMap<Integer,String> found=VideoResolver.probe(this,safe);if(found.isEmpty())putStream(ep,VideoResolver.qualityOf(safe),safe);else for(Map.Entry<Integer,String> e:found.entrySet())putStream(ep,e.getKey(),e.getValue());}}if(ep.streams.isEmpty())throw new IOException("JutSu не вернул прямое видео");}
    private static boolean jutsuTitleUrl(String href){try{Uri u=Uri.parse(href);String h=u.getHost(),path=u.getPath();if(h==null||path==null||!(h.equals("jut.su")||h.endsWith(".jut.su")))return false;if(path.startsWith("/anime/")||path.startsWith("/technique/")||path.contains("episode-")||path.contains("season-")||path.endsWith(".html"))return false;return path.matches("/[a-z0-9][a-z0-9-]+/");}catch(Exception e){return false;}}
    private static Anime anidubShell(String url,String title,String poster,String meta){Anime a=new Anime();a.source="anidub";Matcher m=Pattern.compile("/(\\d+)-[^/]+\\.html").matcher(url);a.id=m.find()?m.group(1):stableId(url);a.alias=safeUrl(url);fillNames(a,title);a.poster=safeUrl(poster);a.year=yearIn(meta);a.episodes=episodesIn(meta+" "+title);a.status=meta!=null&&meta.toLowerCase(Locale.ROOT).contains("онгоинг")?"ongoing":"released";return a;}
    private static Anime jutsuShell(String url,String title,String poster,String meta){Anime a=new Anime();a.source="jutsu";a.id=stableId(url);a.alias=safeUrl(url);fillNames(a,title);a.poster=safeUrl(poster);a.year=yearIn(meta);a.episodes=episodesIn(meta);a.status=meta!=null&&meta.toLowerCase(Locale.ROOT).contains("онгоинг")?"ongoing":"released";return a;}
    private static void fillNames(Anime a,String title){String t=cleanTitle(title);if(t.isEmpty())t="Аниме";String[] parts=t.split("\\s*/\\s*",2);a.title=parts[0].trim();if(parts.length>1)a.original=parts[1].replaceAll("\\s*\\[[^\\]]*\\]\\s*$","").trim();}
