    private static boolean matchesAnime(Anime candidate,Anime base){if(candidate==null||base==null)return false;if(candidate.malId>0&&base.malId>0&&candidate.malId==base.malId)return true;if(candidate.anilistId>0&&base.anilistId>0&&candidate.anilistId==base.anilistId)return true;String bt=plainName(base.title),bo=plainName(base.original),ct=plainName(candidate.title),co=plainName(candidate.original);boolean title=(!bt.isEmpty()&&(bt.equals(ct)||bt.equals(co)))||(!bo.isEmpty()&&(bo.equals(ct)||bo.equals(co)));if(!title&&("anidub".equals(candidate.source)||"jutsu".equals(candidate.source)))title=(!bt.isEmpty()&&(ct.contains(bt)||bt.contains(ct)))||(!bo.isEmpty()&&(co.contains(bo)||bo.contains(co)||ct.contains(bo)));return title&&(base.year==0||candidate.year==0||Math.abs(base.year-candidate.year)<=1);}
